def transform(grid):
    g = np.array(grid)
    bg = background(g)
    objs = objects(g, bg=bg)
    frame = max(objs, key=lambda o: o["size"])
    y0, x0, y1, x1 = frame["box"]
    iy0, ix0, iy1, ix1 = y0 + 1, x0 + 1, y1 - 1, x1 - 1
    seeds = [(y, x) for y in range(iy0, iy1 + 1) for x in range(ix0, ix1 + 1)
             if g[y, x] != bg]
    out = g.copy()
    if not seeds:
        emit(out, "No seed inside the frame; nothing to fill.")
        return out
    dist = {}
    for y in range(iy0, iy1 + 1):
        for x in range(ix0, ix1 + 1):
            if g[y, x] == bg:
                dist[(y, x)] = min(max(abs(y - sy), abs(x - sx)) for sy, sx in seeds)
    maxd = max(dist.values()) if dist else 0
    for d in range(1, maxd + 1):
        col = 4 if d % 2 == 1 else 2
        cells = [p for p, v in dist.items() if v == d]
        if not cells:
            continue
        for (y, x) in cells:
            out[y, x] = col
        emit(out, f"Ring at Chebyshev distance {d} from the seed filled with colour {col} "
                  f"({'odd' if col == 4 else 'even'} distance), clipped to the frame interior.")
    return out
